@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const modal=document.getElementById('assignTaskModal'),priority=modal?.querySelector('select[name="priority"]');if(!modal||!priority)return;modal.classList.add('task-assign-modal');modal.querySelector('.modal-content')?.classList.add('task-assign-content');modal.querySelector('.modal-body>form')?.classList.add('task-assign-form');const title=modal.querySelector('.modal-title');if(title)title.innerHTML='<span class="task-assign-title-icon"><i class="bi bi-send-check"></i></span><span>Giao công việc mới<small>Thiết lập nội dung, thời hạn và người chịu trách nhiệm</small></span>';const field=document.createElement('div');field.className='task-repeat-field';field.innerHTML='<label class="form-label">Lặp công việc</label><select class="form-select mb-2" name="repeat_unit"><option value="none">Không lặp</option><option value="month">Theo tháng</option><option value="week">Theo tuần</option></select><select class="form-select d-none" name="repeat_count"></select><small>Mỗi kỳ được nhắc trước hạn 3 ngày.</small>';priority.closest('.col-md-4').append(field);const unit=field.querySelector('[name="repeat_unit"]'),count=field.querySelector('[name="repeat_count"]'),oldUnit=@json(old('repeat_unit','none')),oldCount=String(@json(old('repeat_count',1)));const refreshRepeat=()=>{const options=unit.value==='month'?[1,2]:unit.value==='week'?[1,2,3,4]:[];count.innerHTML=options.map(value=>`<option value="${value}">${value} ${unit.value==='month'?'tháng':'tuần'}</option>`).join('');count.classList.toggle('d-none',!options.length)};unit.value=['month','week'].includes(oldUnit)?oldUnit:'none';unit.addEventListener('change',refreshRepeat);refreshRepeat();if([...count.options].some(option=>option.value===oldCount))count.value=oldCount;const firstAssignee=modal.querySelector('input[name="assignee_ids[]"]');firstAssignee?.closest('.border')?.classList.add('task-assignee-list');modal.querySelector('[data-task-lead]')?.closest('.col-lg-4')?.classList.add('task-lead-panel');const action=modal.querySelector('.col-12.text-end');action?.classList.add('task-assign-actions');const submit=action?.querySelector('button');if(submit)submit.innerHTML='<i class="bi bi-send-check me-2"></i>Giao công việc'});</script>@endpush
@endsection
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const month=document.querySelector('[data-month-filter]'),quarter=document.querySelector('[data-quarter-filter]');month?.addEventListener('change',()=>{if(month.value&&quarter)quarter.value=''});quarter?.addEventListener('change',()=>{if(quarter.value&&month)month.value=''});const lead=document.querySelector('[data-task-lead]'),items=[...document.querySelectorAll('input[name="assignee_ids[]"]')];if(lead){const old=lead.dataset.oldValue,refresh=()=>{const selected=lead.value||old;lead.innerHTML='<option value="">Chọn người chủ trì</option>';items.filter(i=>i.checked).forEach(i=>lead.add(new Option(i.dataset.assigneeName,i.value,false,i.value===selected)));if(![...lead.options].some(o=>o.value===selected))lead.value=''};items.forEach(i=>i.addEventListener('change',refresh));refresh()}@if($errors->any())const modalId=@json(old('_task_form')==='personal-plan'?'personalPlanModal':'assignTaskModal');const modal=document.getElementById(modalId);if(modal)bootstrap.Modal.getOrCreateInstance(modal).show();@endif});</script>@endpush
